def count_matrix_inversions(m: list[list[int]]) -> int:
    n = len(m)
    invs = 0
    for i in range(n):
        for j in range(n):
            for p in range(i, n):
                for q in range(j, n):
                    if m[i][j] > m[p][q]:
                        invs += 1
    return invs
